return 0,0
end
local SL=math.min(OL,RL)
local TL=hb.base(NL)
if TL<=0 then
return 0,SL
end
return hb.share(NL.unit_id)*(hb.score(hb.whatIf(NL,{xp=PL+SL}))/TL-1)*100,SL
end
function hb.gainFuse(UL)
