function hb.relicWorth(XL,YL)
local ZL=YL._unique_item_data and YL._unique_item_data._unique_relic_data
if not ZL then
return 0
end
local _L=L.Items[YL.item_id]or{}
local aM,bM=R.types(XL.unit_id)
if _L.main_damage_type and _L.main_damage_type~=zad[2195]and _L.main_damage_type~=bM then
return 0
end
local cM,dM=0,0
for eM,fM in pairs(ZL._core_damage_type_buffs or{})do
if aM[fM.damage_type]then
cM=cM+(tonumber(fM.mul)or 0)+(tonumber(fM.add_upg)or 0)*0.01+(tonumber(fM.pen)or 0)*0.001
dM=dM+(tonumber(fM.crit)or 0)
end
end
cM=cM+dM*0.5
local gM=R.rows(XL.unit_id)
local hM=gM and gM[gM.max]
local iM=(hM and tonumber(hM.cd)or 0)*R.mult(XL,zad[1705])
for jM,kM in pairs(ZL._unique_relic_effects or{})do
local lM=type(kM.params)==zad[1557]and kM.params or{}
if kM.id==zad[2196]then
local mM=math.min(1,(tonumber(lM.extra_damage)or 0)*iM/math.max(1,tonumber(lM.time_interval)or 40))
local nM=R.DRONES and R.DRONES[XL.unit_id]
if nM and nM.late and iM>0 then
local oM=1/iM
mM=mM*oM/(oM+(tonumber(nM.max)or 0)*(tonumber(nM.late.dmg)or 0)*(tonumber(nM.hits)or 1)/math.max(0.1,tonumber(nM.late.cd)or 4))
end
cM=cM+mM
elseif kM.id==zad[2197]then
cM=cM+(tonumber(lM.dmg_buff)or 0)*0.25
elseif kM.id==zad[2198]then
cM=cM+(tonumber(lM.dmg_buff)or 0)*dM
elseif kM.id==zad[2199]then
if aM.magic then
cM=0
else
cM=cM+(tonumber(lM.dmg_buff)or 0)*0.3
end
elseif kM.id==zad[2200]then
if aM.water_damage then
cM=cM+0.05
end
end
end
return cM
end
function hb.relicPlan()
