function hb.feedPlan(yP)
local zP=R.trait(yP)
local AP=zP==zad[2228]and 1.5 or 1
local BP=math.max(0,hb.xpFor(yP.unit_id,hb.cap(yP))-(tonumber(yP.xp)or 0))
local CP,DP,FP={},0,0
for GP,HP in ipairs(hb.foodHeld())do
local IP=HP.xp*AP
local JP=math.min(HP.n,math.floor((BP-DP)/math.max(1,IP)))
if JP>0 then
CP[HP.id]=JP
DP=DP+JP*IP
FP=FP+JP
end
end
return{feed=CP,planned=DP,n=FP}
end
function hb.run(KP)
