ab.add(string.format(zad[2231],QP,KP.name),QP,zad[2232],string.format(zad[2233],Q.fmt(XP),ZP))
hb.note(string.format(zad[2234],KP.name,QP,Q.fmt(XP),ZP,math.abs(XP-PP)>PP*0.1 and string.format(zad[2235],Q.fmt(PP))or zad[484]))
else
hb.note(string.format(zad[2236],KP.name,tostring(TP and UP or zad[1853])))
