ab.add(zad[2286]..zR,1,zad[2287],(hR or zad[2288])..(#uR>0 and(zad[2289]..table.concat(uR,zad[1665]))or zad[484]))
E.log(1,zad[2290],zR..zad[2291]..(hR or zad[2288])..(#uR>0 and(zad[2289]..table.concat(uR,zad[1665]))or zad[484]))
U._sigAt=nil
pcall(eb.refresh)
return true,R.name(gR.to)..zad[2292]
end
E.log(1,zad[2290],zad[2293]..R.name(gR.from)..zad[1888]..tostring(pR)..zad[2294]..tostring(qR and qR.unit_id))
