function V.fuseFuel(wS,xS)
local yS=L.session()
local zS={[wS.uuid]=true,[M.evolveUnit]=true,[M.fuseXpUnit]=true}
local AS={}
for BS,CS in ipairs(R.equipped())do
zS[CS.uuid]=true
end
for DS,ES in ipairs(N.savedTeam or{})do
zS[ES]=true
end
for FS,HS in ipairs(N.train and N.train.on and N.train.on.base or{})do
zS[HS]=true
end
for IS,JS in ipairs(N.goals or{})do
zS[JS.uuid]=true
for KS,LS in ipairs(JS.eats or{})do
AS[LS.id]=true
end
end
for MS,NS in ipairs(N.str and N.str.core or{})do
zS[NS]=true
end
local OS=eb.strongest(10)
local PS,QS={},0
for RS,TS in pairs(yS.profile_data.collection.owned_units)do
local US=yS.collection:get_unit_by_uuid(RS)or TS
local VS,WS,XS=pcall(L.USC.is_unit_good_for_fusion,wS,US)
if VS and WS and not(TS._locked or US._locked)and not zS[RS]and not AS[US.unit_id]and not(TS._equipped_relic or US._equipped_relic)and not(TS.shiny or US.shiny)and not R.trait(US)and not(TS.further_modifiers and TS.further_modifiers.limit_break)then
local YS=eb.fodderOrder(US.unit_id)
if YS and not OS[RS]then
local ZS,_S=pcall(R.score,US)
table.insert(PS,{uuid=RS,id=US.unit_id,pts=tonumber(XS)or 1,sc=ZS and _S or 0,order=YS})
QS=QS+(tonumber(XS)or 1)
end
end
end
table.sort(PS,function(aT,bT)
if aT.order~=bT.order then
return aT.order<bT.order
end
if aT.sc~=bT.sc then
return aT.sc<bT.sc
end
return aT.uuid<bT.uuid
end)
local cT,dT={},0
for eT,fT in ipairs(PS)do
if dT>=xS then
break
end
table.insert(cT,fT)
dT=dT+fT.pts
end
return cT,dT,QS
end
