if not(HU._locked or KU._locked)and not(HU._equipped_relic or KU._equipped_relic)then
local MU,NU=pcall(L.USC.calculate_xp_gain_from_fuse,uU,{KU},vU)
NU=MU and tonumber(NU)or 0
if NU>0 then
