function V.autoFuseXp()
if not M.autoFuseXp or M.fuseXpUnit==zad[484]then
return
end
local qV=L.session()
local rV=V.fuseXpTarget(qV)
if not rV then
return
end
local sV=R.name(rV.unit_id)
local tV,uV,vV=V.xpFodder(rV)
if vV<=0 then
V.pickNote.autoFuseXp=nil
return
end
if#tV==0 then
V.pickNote.autoFuseXp=zad[2338]
return
end
if os.time()-(tonumber(M.fuseXpOnAt)or 0)<30 then
V.pickNote.autoFuseXp=zad[2339]
return
end
V.pickNote.autoFuseXp=nil
if E.req.back.fuseXp and Q.now()<E.req.back.fuseXp then
return
end
V.fuseBatch=V.fuseBatch or 50
local wV,xV,yV=0,0,{}
while E.alive and wV<10 and not N.pauseAll do
if wV>0 then
local zV,AV,BV=V.xpFodder(qV.collection:get_unit_by_uuid(M.fuseXpUnit)or rV)
tV,vV={},BV
for CV,DV in ipairs(zV)do
if not yV[DV.uuid]then
table.insert(tV,DV)
end
end
if vV<=0 or#tV==0 then
break
end
end
local EV={}
for FV=1,math.min(V.fuseBatch,#tV)do
table.insert(EV,tV[FV].uuid)
end
local GV=tonumber((qV.collection:get_unit_by_uuid(M.fuseXpUnit)or rV).xp)or 0
local HV=Q.now()
local IV,JV=E.request(zad[2340],zad[2341],M.fuseXpUnit,EV)
if not IV and(JV==zad[1627]or JV==zad[1626])then
