end
xV=xV+1
task.wait(3.5)
continue
end
while Q.now()-HV<5 and(tonumber((qV.collection:get_unit_by_uuid(M.fuseXpUnit)or rV).xp)or 0)<=GV do
task.wait(0.1)
end
local KV=tonumber((qV.collection:get_unit_by_uuid(M.fuseXpUnit)or rV).xp)or 0
if KV>GV then
wV=wV+1
for LV,MV in ipairs(EV)do
yV[MV]=true
end
ab.add(string.format(zad[2342],#EV,sV),#EV,zad[2343],string.format(zad[2344],Q.fmt(KV-GV)))
E.log(1,zad[1772],string.format(zad[2345],#EV,sV,Q.fmt(KV-GV),hb.level(qV.collection:get_unit_by_uuid(M.fuseXpUnit)or rV)))
elseif#EV>20 then
V.fuseBatch=20
E.log(1,zad[1772],string.format(zad[2346],#EV,tostring(E.gameSaid(HV)or(IV and JV)or zad[1853])))
else
local NV=E.gameSaid(HV)
V.pickNote.autoFuseXp=zad[2347]..tostring(NV or(IV and JV)or zad[1853])..zad[2348]
E.log(1,zad[1772],zad[2349]..tostring(NV or(IV and JV)or zad[1853]))
E.backoff(zad[2340],1800)
break
end
end
end
