fb.BONUS=1.5
fb.SLOW=1.4
function fb.boost(rX,sX,tX,uX)
if sX<2 or tX>=math.min(M.dangerReach,(uX or 1)*0.9)then
return
end
local vX=tX<math.min(M.safeReach,(uX or 1)*0.75)
local wX=0
for xX,yX in ipairs(rX)do
if not yX.farm and not yX.train and yX.cost>0 then
wX=math.max(wX,yX.gain/yX.cost)
end
end
for zX,AX in ipairs(rX)do
if AX.train==zad[2420]or(AX.train==zad[2421]and vX)then
AX.gain=math.max(AX.gain,wX*AX.cost*1.05)
end
end
end
