for XJb=0,WJb-1 do
local YJb=TJb:Lerp(UJb,XJb/WJb)
table.insert(W.samples,{pos=YJb,prog=(RJb+VJb*XJb/WJb)/math.max(1,PJb),lane=KJb.Name})
end
RJb=RJb+VJb
end
if MJb[#MJb]then
table.insert(W.samples,{pos=MJb[#MJb],prog=1,lane=KJb.Name})
