function W.baseVerdict(Mic,Nic)
local Oic=(Nic.t or 0)-(Mic.t or 0)
if Oic<W.BASE_WIN-1 then
return false
end
local Pic=((tonumber(Mic.base)or 0)-(tonumber(Nic.base)or 0))/Oic
if Pic<=0 or(tonumber(Nic.base)or 0)<=0 then
return false
end
local Qic=Nic.base/Pic
local Ric,Sic=0,0
local Tic,Uic=Mic.foes or{},Nic.foes or{}
for Vic,Wic in pairs(Uic)do
if Wic.prog>=W.BASE_END then
Ric=Ric+Wic.hp
local Xic=Tic[Vic]
if Xic then
Sic=Sic+math.max(0,Xic.hp-Wic.hp)
end
end
end
for Yic,Zic in pairs(Tic)do
if Zic.prog>=W.BASE_END and not Uic[Yic]then
Sic=Sic+Zic.hp
end
end
if Ric<=0 then
return false
end
local _ic=Sic/Oic
local ajc=_ic>0 and Ric/_ic or math.huge
local bjc={baseTime=Qic,loss=Pic,atEnd=Ric,rate=_ic,killTime=ajc}
return Qic<W.BASE_SOON and ajc>Qic*W.BASE_MARGIN,bjc
end
function W.baseStep(cjc)
