end
end
W.baseTrack=W.baseTrack or{}
local kjc=W.baseTrack
table.insert(kjc,hjc)
while#kjc>1 and hjc.t-kjc[1].t>W.BASE_WIN+2 do
table.remove(kjc,1)
end
local ljc,mjc=W.baseVerdict(kjc[1],hjc)
if cjc then
return ljc,mjc,hjc
end
if not ljc then
return
end
W.bailed=true
N.dg.bails[djc]=(tonumber(N.dg.bails[djc])or 0)+1
N.dg.bail={sig=U.teamSig(),at=os.time()}
pcall(W.styleRecord,false)
E.log(1,zad[3118],string.format(zad[3485],math.floor(100*hjc.base/math.max(1,hjc.baseMax)+0.5),Q.fmt(mjc.loss),math.floor(mjc.baseTime),Q.fmt(mjc.atEnd),Q.fmt(mjc.rate),mjc.killTime==math.huge and zad[3486]or(math.floor(mjc.killTime)..zad[1405])))
E.flush()
E.request(zad[1624],zad[3159])
end
function W.bossStep()
W.focus=nil
if W.random or W.infinite or not(W.total and W.wave()>=W.total)then
