end
local Wjc=tostring(N.dg.room and N.dg.room.seed)
N.dg.bails=type(N.dg.bails)==zad[1557]and N.dg.bails or{}
if W.kind==zad[1577]and not W.bailed and M.bailOut~=false and(Fjc==0 or Ujc<15)and Ajc.net and Ujc>4 and Ujc<60 and(tonumber(N.dg.bails[Wjc])or 0)<3 then
local Xjc=vjc.m and vjc.m:FindFirstChildOfClass(zad[3139])
local Yjc=Xjc and Xjc.MaxHealth or vjc.hp
local Zjc=workspace:FindFirstChild(zad[3484])and workspace._BASES:FindFirstChild(zad[3115])
local _jc=Zjc and Zjc:FindFirstChild(zad[3268])and Zjc.base:FindFirstChild(zad[3269])
local akc=_jc and _jc:FindFirstChildOfClass(zad[3139])
local bkc=akc and akc.Health or(W.info and tonumber(W.info.baseHp))or 100
local ckc=(W.info and tonumber(W.info.baseRel))or db.PRIOR.baseRel
local dkc=vjc.hp-math.max(0,Ajc.net)*Ujc
