N.dg.bails[Wjc]=(tonumber(N.dg.bails[Wjc])or 0)+1
N.dg.bail={sig=U.teamSig(),at=os.time()}
pcall(W.styleRecord,false)
E.log(1,zad[3118],string.format(zad[3491],Q.fmt(dkc),Q.fmt(Ajc.net),math.floor(ekc)))
E.flush()
E.request(zad[1624],zad[3159])
return
end
end
local gkc,hkc
if Ejc==0 and Ujc<30 then
return
end
if Cjc[1]and V.every(zad[3492],2)then
table.sort(Cjc,function(ikc,jkc)
return ikc.spent<jkc.spent
end)
gkc,hkc=Cjc[1],Ejc>0 and zad[3493]or zad[3494]
elseif Vjc and Djc[1]and Ujc>=30 and V.every(zad[3492],8)then
