end
if xkc then
local ykc,zkc=0,Q.flat(xkc)
for Akc,Bkc in ipairs(W.samples)do
if Bkc.prog>=pkc.prog and(Q.flat(Bkc.pos)-zkc).Magnitude<=qkc then
ykc=ykc+1
end
end
if not tkc or ykc>tkc then
skc,tkc=xkc,ykc
end
end
end
end
return skc,tkc or 0
end
function W.focusGain(Ckc)
