if jlc.hand then
hlc[jlc.id]=true
end
end
local klc={}
for llc,mlc in pairs(_kc)do
table.sort(mlc,function(nlc,olc)
if nlc.dps~=olc.dps then
return nlc.dps>olc.dps
end
return nlc.lvl>olc.lvl
end)
table.insert(klc,{id=llc,dps=mlc[1].dps*W.airBoost(mlc[1].m)*W.reach(mlc[1].m)})
end
