Dlc=Dlc or ulc[1]
local Nlc=Dlc.dps*W.airBoost(Dlc.m)*W.reach(Dlc.m)*(tlc==W.planId and 2 or 1)
if(W.mergeIds[tlc]or tlc==W.planId)and(Alc or hlc[tlc])and(not slc or Nlc>slc.score)then
slc={id=tlc,top=Dlc,fresh=Alc,near=Blc or 0,n=Clc or 0,coming=hlc[tlc],score=Nlc}
end
end
W.planId,W.freshM=slc and slc.id,slc and slc.fresh and slc.fresh.m
W.mergeHeldAt=(Xkc and slc and slc.fresh)and(W.mergeHeldAt or W.wave())or nil
if not slc then
