slc.waits=Rlc and Rlc.lvl<=slc.top.lvl and slc.top.lvl<slc.top.max and Slc or false
local Tlc=(not Rlc or Rlc.lvl>=slc.top.lvl)and slc.coming and Slc
local Ulc=W.cloneCard and slc.top.lvl>=slc.top.max and Slc
local Vlc=Rlc and Rlc.lvl>slc.top.lvl and slc.near<0.3*Rlc.dps
