slc.hold=slc.waits and(Xkc or Olc-(W.holdNoCardAt or Olc)<4)
W.mergePlan=slc
E.status(zad[3439],Rlc and string.format(zad[3503],R.name(slc.id),slc.n,slc.n==1 and zad[3504]or zad[3505],Rlc.lvl,slc.ready and zad[3506]or(Xkc and zad[3507]or zad[3508]))or string.format(zad[3509],R.name(slc.id)))
end
