function jb.evoProgress(iPc)
if iPc.ready then
return 1
end
local jPc,kPc,lPc=0,0,{}
for mPc,nPc in ipairs(iPc.plans or{})do
local oPc=tonumber(nPc.need)or 0
if nPc.item then
lPc[nPc.item]=true
end
if oPc>0 then
jPc=jPc+math.min(1,(tonumber(nPc.have)or 0)/oPc)
kPc=kPc+1
end
end
for pPc,qPc in ipairs(iPc.items or{})do
if not lPc[qPc.id]then
jPc=jPc+1
kPc=kPc+1
end
end
return kPc>0 and jPc/kPc or 0
end
